-- PrepForge starter bank: 150 original multiple-choice practice questions.
-- Run this in Supabase SQL Editor after applying the question-practice schema.
-- Re-running is safe: existing questions with the same topic and prompt are skipped.

begin;

insert into public.topics (name, category, description) values
  ('CN', 'technical', 'Computer Networks practice questions.'),
  ('DBMS', 'technical', 'Database Management Systems practice questions.'),
  ('DSA', 'technical', 'Data Structures and Algorithms practice questions.'),
  ('HR', 'hr', 'Behavioral and human-resources interview practice questions.'),
  ('Java', 'technical', 'Java programming practice questions.'),
  ('OS', 'technical', 'Operating Systems practice questions.'),
  ('Python', 'technical', 'Python programming practice questions.'),
  ('Quant', 'aptitude', 'Quantitative aptitude practice questions.'),
  ('Technical fundamentals', 'technical', 'General software engineering practice questions.')
on conflict (name) do update set
  category = excluded.category,
  description = excluded.description;

insert into public.questions (
  topic_id, question_type, difficulty, prompt, options, correct_answer, explanation
)
select
  t.id, q.question_type, q.difficulty, q.prompt, q.options::jsonb,
  q.correct_answer, q.explanation
from (values
  -- Quant (20)
  ('Quant', 'aptitude', 'easy', 'What is 15% of 200?', '["20", "30", "35", "40"]', '30', '10% of 200 is 20 and 5% is 10, so 15% is 30.'),
  ('Quant', 'aptitude', 'easy', 'A product costs 800 after a 20% discount. What was its original price?', '["900", "960", "1,000", "1,200"]', '1,000', 'The sale price is 80% of the original, and 800 divided by 0.8 is 1,000.'),
  ('Quant', 'aptitude', 'easy', 'What is the average of 8, 12, 16, and 20?', '["12", "14", "15", "16"]', '14', 'Their sum is 56, and 56 divided by 4 is 14.'),
  ('Quant', 'aptitude', 'easy', 'A car travels 150 km in 3 hours. What is its average speed?', '["40 km/h", "45 km/h", "50 km/h", "60 km/h"]', '50 km/h', 'Average speed is distance divided by time: 150 divided by 3 is 50 km/h.'),
  ('Quant', 'aptitude', 'easy', 'Two numbers are in the ratio 2:3 and their sum is 40. What is the smaller number?', '["12", "16", "20", "24"]', '16', 'There are 5 total parts, so each part is 8. The smaller number is 2 times 8.'),
  ('Quant', 'aptitude', 'easy', 'What is the simple interest on 1,000 at 5% per year for 2 years?', '["50", "100", "150", "200"]', '100', 'Simple interest is principal times rate times time: 1,000 x 0.05 x 2 = 100.'),
  ('Quant', 'aptitude', 'easy', 'What number comes next: 3, 6, 12, 24, ...?', '["30", "36", "48", "60"]', '48', 'Each term is twice the previous term.'),
  ('Quant', 'aptitude', 'easy', 'A fair six-sided die is rolled once. What is the probability of rolling a number greater than 4?', '["1/6", "1/3", "1/2", "2/3"]', '1/3', 'The outcomes 5 and 6 are favorable, so the probability is 2/6 or 1/3.'),
  ('Quant', 'aptitude', 'easy', 'If 5 workers finish a job in 12 days at the same rate, how many worker-days does the job require?', '["17", "50", "60", "72"]', '60', 'The total work is 5 workers times 12 days, or 60 worker-days.'),
  ('Quant', 'aptitude', 'easy', 'A shirt marked at 1,500 is sold at a 10% discount. What is the sale price?', '["1,250", "1,300", "1,350", "1,400"]', '1,350', 'Ten percent of 1,500 is 150; subtracting gives 1,350.'),
  ('Quant', 'aptitude', 'medium', 'A can complete a task in 6 days and B in 3 days. How long do they take together at constant rates?', '["1 day", "2 days", "3 days", "4 days"]', '2 days', 'Their combined rate is 1/6 + 1/3 = 1/2 of the task per day.'),
  ('Quant', 'aptitude', 'medium', 'A value increases from 80 to 100. What is the percentage increase?', '["20%", "25%", "30%", "40%"]', '25%', 'The increase is 20; 20 divided by the original 80 is 25%.'),
  ('Quant', 'aptitude', 'medium', 'What is the least common multiple of 12 and 18?', '["24", "30", "36", "72"]', '36', '36 is the smallest positive number divisible by both 12 and 18.'),
  ('Quant', 'aptitude', 'medium', 'A train 120 m long passes a pole in 6 seconds. What is its speed?', '["15 m/s", "20 m/s", "24 m/s", "30 m/s"]', '20 m/s', 'Speed is length divided by time: 120 divided by 6 equals 20 m/s.'),
  ('Quant', 'aptitude', 'medium', 'If x + 7 = 19, what is x?', '["10", "11", "12", "13"]', '12', 'Subtract 7 from both sides to get x = 12.'),
  ('Quant', 'aptitude', 'medium', 'A bag contains 3 red and 5 blue balls. What is the probability of selecting a red ball?', '["3/8", "5/8", "1/3", "1/2"]', '3/8', 'There are 3 red balls among 8 balls total.'),
  ('Quant', 'aptitude', 'medium', 'What is the perimeter of a rectangle with length 9 cm and width 4 cm?', '["13 cm", "26 cm", "36 cm", "72 cm"]', '26 cm', 'The perimeter is 2 times (9 + 4), which is 26 cm.'),
  ('Quant', 'aptitude', 'medium', 'A person spends 3/5 of a 2,000 budget. How much remains?', '["600", "800", "1,000", "1,200"]', '800', 'The amount spent is 1,200, leaving 800.'),
  ('Quant', 'aptitude', 'medium', 'What is the median of 3, 7, 9, 12, and 15?', '["7", "9", "10", "12"]', '9', 'The middle value in the ordered list is 9.'),
  ('Quant', 'aptitude', 'medium', 'A number is divided by 4 and then increased by 3 to give 8. What is the number?', '["12", "16", "20", "24"]', '20', 'If n/4 + 3 = 8, then n/4 = 5 and n = 20.'),

  -- CN (20)
  ('CN', 'technical', 'easy', 'What does DNS primarily do?', '["Maps domain names to IP addresses", "Encrypts disk drives", "Assigns MAC addresses", "Compresses web pages"]', 'Maps domain names to IP addresses', 'DNS resolves human-readable domain names to network addresses.'),
  ('CN', 'technical', 'easy', 'Which transport protocol provides reliable, ordered delivery?', '["UDP", "TCP", "ARP", "ICMP"]', 'TCP', 'TCP provides reliable, ordered byte-stream delivery between endpoints.'),
  ('CN', 'technical', 'easy', 'What is the default port for HTTPS?', '["21", "80", "443", "8080"]', '443', 'HTTPS commonly uses TCP port 443.'),
  ('CN', 'technical', 'easy', 'What does LAN stand for?', '["Local Area Network", "Large Access Node", "Linked Address Number", "Long Area Net"]', 'Local Area Network', 'A LAN connects devices across a limited geographic area.'),
  ('CN', 'technical', 'easy', 'What is a router primarily used for?', '["Forwarding packets between networks", "Displaying web pages", "Storing files", "Converting source code"]', 'Forwarding packets between networks', 'Routers direct packets between different IP networks.'),
  ('CN', 'technical', 'easy', 'Which protocol can automatically assign IP configuration to a client?', '["DHCP", "FTP", "SMTP", "SSH"]', 'DHCP', 'DHCP leases IP settings and other network configuration to clients.'),
  ('CN', 'technical', 'easy', 'What does a MAC address identify?', '["A network interface at the link layer", "A website", "A user account", "A TCP connection"]', 'A network interface at the link layer', 'A MAC address is a link-layer identifier used on local networks.'),
  ('CN', 'technical', 'easy', 'Which protocol is commonly used by ping?', '["ICMP", "HTTP", "SMTP", "SNMP"]', 'ICMP', 'Ping commonly uses ICMP echo request and echo reply messages.'),
  ('CN', 'technical', 'easy', 'Which standard family is associated with Wi-Fi?', '["IEEE 802.11", "IEEE 802.3", "IEEE 1394", "IEEE 802.1X"]', 'IEEE 802.11', 'Wi-Fi is based on the IEEE 802.11 family of standards.'),
  ('CN', 'technical', 'easy', 'How long is an IPv4 address?', '["16 bits", "32 bits", "64 bits", "128 bits"]', '32 bits', 'An IPv4 address consists of 32 bits.'),
  ('CN', 'technical', 'medium', 'How long is an IPv6 address?', '["32 bits", "64 bits", "128 bits", "256 bits"]', '128 bits', 'IPv6 addresses are 128 bits long.'),
  ('CN', 'technical', 'medium', 'What does a subnet mask identify?', '["Network and host portions of an IP address", "The encryption key", "The DNS server software", "The physical cable type"]', 'Network and host portions of an IP address', 'The mask indicates which address bits identify the network prefix and which identify the host.'),
  ('CN', 'technical', 'medium', 'What is the default port for HTTP?', '["22", "25", "80", "443"]', '80', 'HTTP commonly uses TCP port 80.'),
  ('CN', 'technical', 'medium', 'How does an Ethernet switch commonly decide where to send a frame?', '["Using destination MAC addresses", "Using URL paths", "Using file extensions", "Using DNS names"]', 'Using destination MAC addresses', 'A switch learns MAC addresses on its ports and forwards frames based on the destination MAC.'),
  ('CN', 'technical', 'medium', 'Which statement best describes UDP?', '["It does not guarantee delivery or ordering", "It always retransmits lost packets", "It requires a connection handshake", "It guarantees packets arrive in order"]', 'It does not guarantee delivery or ordering', 'UDP is connectionless and makes no delivery or ordering guarantees.'),
  ('CN', 'technical', 'medium', 'What is a default gateway used for?', '["Forwarding traffic to destinations outside the local network", "Resolving all domain names", "Assigning MAC addresses", "Filtering source code"]', 'Forwarding traffic to destinations outside the local network', 'A host sends off-subnet traffic to its configured default gateway.'),
  ('CN', 'technical', 'medium', 'Which protocol securely provides remote terminal access?', '["Telnet", "SSH", "TFTP", "POP3"]', 'SSH', 'SSH provides encrypted remote login and command execution.'),
  ('CN', 'technical', 'medium', 'What is the main purpose of a firewall?', '["Filter network traffic according to rules", "Convert IPv4 to source code", "Increase network cable length", "Assign host names"]', 'Filter network traffic according to rules', 'A firewall allows or blocks traffic based on configured security policy.'),
  ('CN', 'technical', 'medium', 'What does traceroute help reveal?', '["Network hops toward a destination", "Saved browser passwords", "The contents of a database", "The Wi-Fi encryption key"]', 'Network hops toward a destination', 'Traceroute probes the path and reports intermediate routers where responses are received.'),
  ('CN', 'technical', 'medium', 'What is the purpose of ARP in an IPv4 local network?', '["Resolve an IPv4 address to a link-layer address", "Resolve a domain name to a URL", "Encrypt a TCP segment", "Assign a public IP address"]', 'Resolve an IPv4 address to a link-layer address', 'ARP discovers the link-layer address associated with an IPv4 address on the local network.'),

  -- DBMS (20)
  ('DBMS', 'technical', 'easy', 'What is a primary key used for?', '["Uniquely identifying a row", "Sorting every query", "Encrypting a table", "Allowing duplicate identifiers"]', 'Uniquely identifying a row', 'A primary key uniquely identifies each row in a table.'),
  ('DBMS', 'technical', 'easy', 'What does a foreign key represent?', '["A reference to a key in another or the same table", "A database password", "A file stored outside the database", "An automatically created index only"]', 'A reference to a key in another or the same table', 'A foreign key enforces a relationship by referencing a key in a related table.'),
  ('DBMS', 'technical', 'easy', 'Which SQL command retrieves rows from a table?', '["SELECT", "FETCHFILE", "RETRIEVE", "READTABLE"]', 'SELECT', 'SELECT is the SQL statement used to query rows.'),
  ('DBMS', 'technical', 'easy', 'Which SQL clause filters rows before grouping?', '["WHERE", "HAVING", "ORDER BY", "LIMIT"]', 'WHERE', 'WHERE filters individual rows before grouping and aggregation.'),
  ('DBMS', 'technical', 'easy', 'What does COUNT(*) return?', '["The number of rows", "The sum of numeric columns", "The largest string", "The number of tables"]', 'The number of rows', 'COUNT(*) counts rows in the selected result.'),
  ('DBMS', 'technical', 'easy', 'Which JOIN returns rows with matching values in both tables?', '["INNER JOIN", "LEFT JOIN", "CROSS JOIN", "FULL OUTER JOIN"]', 'INNER JOIN', 'INNER JOIN returns rows where the join condition matches on both sides.'),
  ('DBMS', 'technical', 'easy', 'What is a database index commonly used for?', '["Speeding up data lookups", "Replacing all constraints", "Encrypting every column", "Removing duplicate tables"]', 'Speeding up data lookups', 'Indexes can improve lookup performance, with storage and write-maintenance costs.'),
  ('DBMS', 'technical', 'easy', 'Which SQL command changes existing rows?', '["UPDATE", "ALTER", "CREATE", "GRANT"]', 'UPDATE', 'UPDATE modifies values in existing rows.'),
  ('DBMS', 'technical', 'easy', 'Which SQL keyword removes duplicate rows from a result?', '["DISTINCT", "UNIQUE ROWS", "ONLY", "SINGLE"]', 'DISTINCT', 'SELECT DISTINCT returns unique combinations of the selected columns.'),
  ('DBMS', 'technical', 'easy', 'What does NULL generally represent in SQL?', '["A missing or unknown value", "The number zero", "An empty string in every database", "A false boolean value"]', 'A missing or unknown value', 'NULL represents an absent or unknown value and is tested with IS NULL.'),
  ('DBMS', 'technical', 'medium', 'In ACID properties, what does atomicity mean?', '["A transaction happens completely or not at all", "Every query uses an index", "Data is always duplicated", "Transactions run alphabetically"]', 'A transaction happens completely or not at all', 'Atomicity makes a transaction all-or-nothing.'),
  ('DBMS', 'technical', 'medium', 'What does the consistency property of ACID ensure?', '["Transactions preserve database rules and constraints", "Every transaction has the same duration", "All data is stored in one table", "Queries never use locks"]', 'Transactions preserve database rules and constraints', 'A committed transaction moves the database from one valid state to another.'),
  ('DBMS', 'technical', 'medium', 'What does isolation aim to provide?', '["Concurrent transactions behave without improper interference", "Every table is hidden", "Backups run automatically", "Queries avoid all indexes"]', 'Concurrent transactions behave without improper interference', 'Isolation controls how concurrent transactions observe one another''s intermediate work.'),
  ('DBMS', 'technical', 'medium', 'What does durability mean in ACID?', '["Committed changes persist despite a system restart", "Uncommitted changes are always saved", "Every query runs once", "Rows cannot be deleted"]', 'Committed changes persist despite a system restart', 'Durability ensures committed data survives failures according to the database''s guarantees.'),
  ('DBMS', 'technical', 'medium', 'What is normalization primarily intended to reduce?', '["Redundant data and update anomalies", "The number of SQL keywords", "The number of users", "Network bandwidth"]', 'Redundant data and update anomalies', 'Normalization organizes relations to reduce duplication and modification anomalies.'),
  ('DBMS', 'technical', 'medium', 'Which clause filters grouped results after aggregation?', '["HAVING", "WHERE", "FROM", "VALUES"]', 'HAVING', 'HAVING filters groups, often using aggregate expressions.'),
  ('DBMS', 'technical', 'medium', 'What does a LEFT JOIN preserve?', '["All rows from the left table", "Only unmatched rows from the right table", "Only rows that appear in both tables", "No rows containing NULL"]', 'All rows from the left table', 'A LEFT JOIN includes every left-side row and matching right-side data when available.'),
  ('DBMS', 'technical', 'medium', 'What is a transaction savepoint used for?', '["Marking a point to which part of a transaction can roll back", "Creating a permanent backup", "Creating a new database user", "Sorting query output"]', 'Marking a point to which part of a transaction can roll back', 'A savepoint lets a transaction roll back to an intermediate marker.'),
  ('DBMS', 'technical', 'medium', 'What is a composite key?', '["A key made from multiple columns", "A key stored only in memory", "A key with no values", "An index on every table"]', 'A key made from multiple columns', 'A composite key uses two or more columns together to identify a row.'),
  ('DBMS', 'technical', 'medium', 'What is a common purpose of EXPLAIN in SQL databases?', '["Inspecting a query execution plan", "Changing a column type", "Creating a user password", "Exporting a table as an image"]', 'Inspecting a query execution plan', 'EXPLAIN displays how the database plans to execute a query.'),

  -- DSA (20)
  ('DSA', 'technical', 'easy', 'Which data structure follows Last In, First Out?', '["Queue", "Stack", "Heap", "Graph"]', 'Stack', 'A stack removes the most recently added item first.'),
  ('DSA', 'technical', 'easy', 'Which data structure follows First In, First Out?', '["Stack", "Queue", "Tree", "Set"]', 'Queue', 'A queue removes items in the order they were added.'),
  ('DSA', 'technical', 'easy', 'What is the time complexity of accessing an array element by index?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 'O(1)', 'Array indexing uses the base address and offset, so access is constant time.'),
  ('DSA', 'technical', 'easy', 'Which traversal of a binary search tree visits keys in sorted order?', '["Inorder", "Preorder", "Postorder", "Level order"]', 'Inorder', 'Inorder visits left subtree, node, then right subtree, yielding sorted keys in a BST.'),
  ('DSA', 'technical', 'easy', 'Which data structure is commonly used to implement breadth-first search?', '["Queue", "Stack", "Hash set only", "Priority queue only"]', 'Queue', 'BFS explores nodes in layers using a FIFO queue.'),
  ('DSA', 'technical', 'easy', 'Which data structure is commonly used to implement depth-first search iteratively?', '["Stack", "Queue", "Array sorted by value", "Circular buffer only"]', 'Stack', 'An explicit stack supports DFS by processing the most recently discovered node.'),
  ('DSA', 'technical', 'easy', 'What is the worst-case time complexity of linear search in an array of n items?', '["O(1)", "O(log n)", "O(n)", "O(n squared)"]', 'O(n)', 'In the worst case, linear search examines every element.'),
  ('DSA', 'technical', 'easy', 'Which structure is designed to efficiently retrieve a value by key on average?', '["Hash table", "Stack", "Queue", "Linked list"]', 'Hash table', 'A hash table provides average constant-time key lookup under suitable conditions.'),
  ('DSA', 'technical', 'easy', 'In a singly linked list, what does each node usually store besides its value?', '["A reference to the next node", "Its sorted rank", "Every other node''s value", "A database transaction"]', 'A reference to the next node', 'Each node links to the next node in the list.'),
  ('DSA', 'technical', 'easy', 'Which structure is commonly used to represent hierarchical data?', '["Tree", "Queue", "Stack", "Hash function"]', 'Tree', 'Trees represent parent-child relationships and hierarchical structure.'),
  ('DSA', 'technical', 'medium', 'What condition is required for binary search on a conventional array?', '["The elements are sorted", "The elements are all distinct", "The length is even", "The array contains only integers"]', 'The elements are sorted', 'Binary search relies on sorted order to discard half of the remaining search range.'),
  ('DSA', 'technical', 'medium', 'What is the time complexity of binary search on a sorted array?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 'O(log n)', 'Each comparison halves the remaining search interval.'),
  ('DSA', 'technical', 'medium', 'What is the average time complexity of merge sort?', '["O(log n)", "O(n)", "O(n log n)", "O(n squared)"]', 'O(n log n)', 'Merge sort divides the input recursively and merges in linear time per level.'),
  ('DSA', 'technical', 'medium', 'What is the worst-case time complexity of quicksort with consistently poor pivots?', '["O(log n)", "O(n)", "O(n log n)", "O(n squared)"]', 'O(n squared)', 'Highly unbalanced partitions can lead to quadratic work.'),
  ('DSA', 'technical', 'medium', 'Which shortest-path algorithm supports negative edge weights but not negative cycles?', '["Dijkstra", "Bellman-Ford", "Breadth-first search", "Prim"]', 'Bellman-Ford', 'Bellman-Ford handles negative edge weights and can detect reachable negative cycles.'),
  ('DSA', 'technical', 'medium', 'What is the average lookup time in a well-distributed hash table?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 'O(1)', 'With a suitable hash function and controlled load factor, lookup is constant time on average.'),
  ('DSA', 'technical', 'medium', 'Which data structure is typically used to efficiently retrieve the minimum-priority item?', '["Min-heap", "Stack", "Queue", "Linked list without ordering"]', 'Min-heap', 'A min-heap keeps the smallest key at its root for efficient retrieval.'),
  ('DSA', 'technical', 'medium', 'What is the space complexity of an adjacency matrix for a graph with V vertices?', '["O(V)", "O(V + E)", "O(V squared)", "O(E squared)"]', 'O(V squared)', 'The matrix stores a cell for every possible pair of vertices.'),
  ('DSA', 'technical', 'medium', 'Which algorithmic strategy solves a problem by combining solutions to overlapping subproblems?', '["Dynamic programming", "Linear search", "Hashing", "Random permutation"]', 'Dynamic programming', 'Dynamic programming stores subproblem results to avoid repeated computation.'),
  ('DSA', 'technical', 'medium', 'What is a stable sorting algorithm?', '["One that preserves the relative order of equal-key items", "One that always runs in O(1)", "One that never uses memory", "One that sorts only integers"]', 'One that preserves the relative order of equal-key items', 'Stability means equal-key elements retain their original relative order.'),

  -- OS (20)
  ('OS', 'technical', 'easy', 'What is the main role of an operating system?', '["Managing hardware resources and providing services to programs", "Compiling every application automatically", "Replacing the CPU", "Designing web pages"]', 'Managing hardware resources and providing services to programs', 'An OS manages resources and offers common services to applications.'),
  ('OS', 'technical', 'easy', 'What is a process?', '["A program in execution", "A file extension", "A type of network cable", "A database index"]', 'A program in execution', 'A process is an executing program with associated state and resources.'),
  ('OS', 'technical', 'easy', 'What is a thread?', '["A unit of execution within a process", "A type of hard drive", "A network address", "A stored procedure"]', 'A unit of execution within a process', 'A thread is a schedulable execution path within a process.'),
  ('OS', 'technical', 'easy', 'What is virtual memory?', '["A technique that gives processes an address space backed by memory and storage", "A second physical CPU", "A type of file compression", "A network protocol"]', 'A technique that gives processes an address space backed by memory and storage', 'Virtual memory maps process addresses to physical memory and may use storage as backing.'),
  ('OS', 'technical', 'easy', 'Which component decides which ready process or thread runs next?', '["CPU scheduler", "Text editor", "File compressor", "DNS resolver"]', 'CPU scheduler', 'The scheduler selects a runnable process or thread for CPU time.'),
  ('OS', 'technical', 'easy', 'What is a file system responsible for?', '["Organizing and managing stored files", "Routing internet packets", "Rendering graphics", "Compiling source code"]', 'Organizing and managing stored files', 'A file system organizes data and metadata on storage devices.'),
  ('OS', 'technical', 'easy', 'What does RAM primarily provide?', '["Volatile working memory", "Permanent optical storage", "Network name resolution", "CPU instruction decoding"]', 'Volatile working memory', 'RAM holds data and instructions currently in use and is generally volatile.'),
  ('OS', 'technical', 'easy', 'What is a system call?', '["A controlled request for a service from the operating system kernel", "A call to a remote website only", "A CPU hardware failure", "A database table constraint"]', 'A controlled request for a service from the operating system kernel', 'Programs use system calls to request kernel-managed operations.'),
  ('OS', 'technical', 'easy', 'What is multitasking?', '["Managing execution of multiple tasks over time", "Running only one application ever", "Duplicating every file", "Increasing a network''s bandwidth"]', 'Managing execution of multiple tasks over time', 'The OS schedules tasks so multiple programs can make progress.'),
  ('OS', 'technical', 'easy', 'What does a device driver do?', '["Enables the OS to communicate with a hardware device", "Encrypts every user password", "Stores a web page", "Replaces the scheduler"]', 'Enables the OS to communicate with a hardware device', 'Drivers provide software interfaces for controlling specific hardware.'),
  ('OS', 'technical', 'medium', 'What is a deadlock?', '["A state where processes wait indefinitely for resources held by one another", "A fast context switch", "A completed transaction", "A type of file system"]', 'A state where processes wait indefinitely for resources held by one another', 'Deadlock occurs when a set of processes cannot proceed because of circular resource waits.'),
  ('OS', 'technical', 'medium', 'Which is one necessary condition for deadlock?', '["Circular wait", "Unlimited resources", "No process ownership", "Only one process in the system"]', 'Circular wait', 'Circular wait is one of the four Coffman conditions associated with deadlock.'),
  ('OS', 'technical', 'medium', 'What is a context switch?', '["Saving one execution context and restoring another", "Changing a file extension", "Switching from IPv4 to IPv6", "Compressing a process"]', 'Saving one execution context and restoring another', 'A context switch changes which process or thread is executing on a CPU.'),
  ('OS', 'technical', 'medium', 'What does paging divide virtual memory into?', '["Fixed-size pages", "Variable-size files only", "CPU registers", "Network frames"]', 'Fixed-size pages', 'Paging divides virtual address spaces into fixed-size pages mapped to physical frames.'),
  ('OS', 'technical', 'medium', 'What is a page fault?', '["An access to a page that is not currently mapped in physical memory", "A syntax error in a file", "A failed DNS lookup", "A CPU temperature warning"]', 'An access to a page that is not currently mapped in physical memory', 'A page fault traps to the OS so it can resolve a missing or invalid page mapping.'),
  ('OS', 'technical', 'medium', 'What is a mutex primarily used for?', '["Mutual exclusion when accessing shared state", "Sorting a file", "Assigning IP addresses", "Creating processes"]', 'Mutual exclusion when accessing shared state', 'A mutex protects a critical section so only one owner accesses it at a time.'),
  ('OS', 'technical', 'medium', 'What is a semaphore commonly used to coordinate?', '["Access to shared resources or signaling between tasks", "Domain name resolution", "Disk formatting only", "Source code compilation"]', 'Access to shared resources or signaling between tasks', 'Semaphores provide synchronization and resource-counting mechanisms.'),
  ('OS', 'technical', 'medium', 'What does a preemptive scheduler allow?', '["The OS to interrupt a running task and schedule another", "A process to bypass all permissions", "An application to modify kernel memory freely", "A disk to run without a controller"]', 'The OS to interrupt a running task and schedule another', 'Preemption lets the OS take the CPU from a running task, often after a time slice.'),
  ('OS', 'technical', 'medium', 'What is thrashing in a virtual-memory system?', '["Excessive paging that leaves little time for useful execution", "A fast cache lookup", "A completed backup", "A process using no memory"]', 'Excessive paging that leaves little time for useful execution', 'Thrashing occurs when frequent page faults and swapping dominate system activity.'),
  ('OS', 'technical', 'medium', 'What is a zombie process in Unix-like systems?', '["A terminated process whose exit status has not yet been collected", "A process that runs without memory", "A kernel thread with no parent", "A process waiting for network input"]', 'A terminated process whose exit status has not yet been collected', 'A zombie has exited but remains in the process table until its parent collects its status.'),

  -- Java (15)
  ('Java', 'technical', 'easy', 'Which component executes Java bytecode?', '["JVM", "Javadoc", "Maven", "JDBC"]', 'JVM', 'The Java Virtual Machine loads and executes bytecode.'),
  ('Java', 'technical', 'easy', 'Which Java type is a primitive type?', '["int", "String", "Integer", "ArrayList"]', 'int', 'int is a Java primitive; String, Integer, and ArrayList are reference types.'),
  ('Java', 'technical', 'easy', 'Which keyword creates a subclass in Java?', '["extends", "inherits", "implements", "instanceof"]', 'extends', 'A class uses extends to inherit from another class.'),
  ('Java', 'technical', 'easy', 'Which keyword declares that a class implements an interface?', '["implements", "extends", "interfaceOf", "inherits"]', 'implements', 'A class declares implemented interfaces with the implements keyword.'),
  ('Java', 'technical', 'easy', 'Which collection is a resizable array implementation?', '["ArrayList", "TreeSet", "HashMap", "PriorityQueue"]', 'ArrayList', 'ArrayList stores elements in a resizable array.'),
  ('Java', 'technical', 'easy', 'What does == compare for two object references?', '["Whether they refer to the same object", "Whether all fields are equal", "Whether their text is equal", "Whether they have the same hash code"]', 'Whether they refer to the same object', 'For references, == tests identity.'),
  ('Java', 'technical', 'easy', 'Which method is the conventional entry point for a Java application?', '["public static void main(String[] args)", "public void start()", "static int run()", "private static void init()"]', 'public static void main(String[] args)', 'The Java launcher conventionally invokes the public static main method with a String array.'),
  ('Java', 'technical', 'medium', 'What is true of Java String objects?', '["They are immutable", "They are always mutable", "They are primitive values", "They cannot be compared"]', 'They are immutable', 'String operations that appear to modify a string return another String rather than changing the original.'),
  ('Java', 'technical', 'medium', 'What is method overloading?', '["Methods with the same name and different parameter lists", "A subclass replacing an inherited method", "Calling a method recursively", "Creating two packages with the same name"]', 'Methods with the same name and different parameter lists', 'Overloaded methods share a name but differ in their parameter signatures.'),
  ('Java', 'technical', 'medium', 'What is method overriding?', '["A subclass provides an implementation for an inherited method", "A class defines methods with different names", "A method calls itself", "A constructor returns a value"]', 'A subclass provides an implementation for an inherited method', 'Overriding lets a subclass specialize an inherited instance method.'),
