  ('HR', 'hr', 'easy', 'What does STAR stand for in behavioral interviewing?', '["Situation, Task, Action, Result", "Skill, Target, Answer, Review", "Start, Test, Apply, Repeat", "Summary, Topic, Aim, Response"]', 'Situation, Task, Action, Result', 'STAR structures an example around its context, responsibility, actions, and outcome.'),
  ('HR', 'hr', 'easy', 'When asked about a weakness, what is a constructive approach?', '["Name a genuine development area and explain steps you are taking", "Claim to have no weaknesses", "Blame a coworker", "Avoid answering"]', 'Name a genuine development area and explain steps you are taking', 'A credible answer shows self-awareness and practical improvement.'),
  ('HR', 'hr', 'easy', 'A teammate disagrees with your proposal. What is a good first step?', '["Listen to their reasoning and clarify the shared goal", "Escalate immediately", "Stop communicating", "Insist without discussion"]', 'Listen to their reasoning and clarify the shared goal', 'Listening first helps identify concerns and keeps the conversation constructive.'),
  ('HR', 'hr', 'easy', 'What is a strong way to describe an accomplishment?', '["Explain your contribution and a specific, truthful result", "List unrelated duties", "Take credit for the whole team", "Use an unsupported estimate as fact"]', 'Explain your contribution and a specific, truthful result', 'Clear individual actions and accurate outcomes help the interviewer understand your impact.'),
  ('HR', 'hr', 'easy', 'How should you respond to constructive feedback?', '["Ask clarifying questions and apply useful points", "Ignore it", "Argue before understanding it", "Share it as a complaint"]', 'Ask clarifying questions and apply useful points', 'Understanding feedback and acting on it demonstrates coachability.'),
  ('HR', 'hr', 'medium', 'What should you do if you do not know an interview answer?', '["Be honest, explain what you do know, and describe how you would find out", "Invent a confident answer", "Change the subject without explanation", "End the interview"]', 'Be honest, explain what you do know, and describe how you would find out', 'Honesty and a reasoned approach show judgment even when knowledge is incomplete.'),
  ('HR', 'hr', 'medium', 'When discussing a conflict at work, what should your example emphasize?', '["Your constructive actions and the resolution", "Insults about the other person", "Only who was at fault", "Private details unrelated to work"]', 'Your constructive actions and the resolution', 'Focus on professional behavior, communication, and what changed as a result.'),
  ('HR', 'hr', 'medium', 'What is a useful way to answer “Why do you want this role?”', '["Connect the role requirements to your skills and genuine interests", "Say only that you need any job", "Criticize other employers", "Repeat the job title"]', 'Connect the role requirements to your skills and genuine interests', 'A specific connection demonstrates preparation and authentic motivation.'),
  ('HR', 'hr', 'medium', 'How can you make a behavioral interview answer easier to follow?', '["Give brief context, explain your actions, and state the outcome", "Start with unrelated background", "Avoid describing your own role", "Use as many technical acronyms as possible"]', 'Give brief context, explain your actions, and state the outcome', 'A concise structure helps the interviewer follow the example and your contribution.'),
  ('HR', 'hr', 'medium', 'What is a useful question to ask an interviewer near the end?', '["How will success in this role be evaluated?", "Can I skip the role requirements?", "Why is the team disorganized?", "Can you decide before I leave?"]', 'How will success in this role be evaluated?', 'Asking about success criteria clarifies expectations and shows interest in contributing.'),

  -- Technical fundamentals (10)
  ('Technical fundamentals', 'technical', 'easy', 'What does version control help a team do?', '["Track and collaborate on changes to files", "Run a database server", "Replace testing", "Encrypt all network traffic"]', 'Track and collaborate on changes to files', 'Version control records changes and supports collaboration and history.'),
  ('Technical fundamentals', 'technical', 'easy', 'What is the purpose of a unit test?', '["Check a small unit of behavior in isolation", "Measure internet speed", "Deploy an application", "Create a database schema automatically"]', 'Check a small unit of behavior in isolation', 'Unit tests verify focused behavior of a small component.'),
  ('Technical fundamentals', 'technical', 'easy', 'What is an API?', '["A defined interface through which software components communicate", "A computer processor", "A type of database index", "A programming language keyword"]', 'A defined interface through which software components communicate', 'An API specifies operations or data that one software component exposes to another.'),
  ('Technical fundamentals', 'technical', 'easy', 'What does JSON primarily represent?', '["Structured data using objects and arrays", "A compiled executable", "A network cable standard", "A relational database engine"]', 'Structured data using objects and arrays', 'JSON is a text-based format for structured data.'),
  ('Technical fundamentals', 'technical', 'easy', 'What does HTTPS add to HTTP in typical web communication?', '["TLS-protected transport", "Automatic database backups", "A faster CPU", "A different HTML syntax"]', 'TLS-protected transport', 'HTTPS uses TLS to protect communication and authenticate the server.'),
  ('Technical fundamentals', 'technical', 'medium', 'What is the main benefit of code review?', '["Finding issues and sharing feedback before or after changes are merged", "Guaranteeing code has no bugs", "Replacing automated tests", "Automatically improving runtime speed"]', 'Finding issues and sharing feedback before or after changes are merged', 'Code review helps catch defects and improves maintainability and shared understanding.'),
  ('Technical fundamentals', 'technical', 'medium', 'What does continuous integration commonly do?', '["Builds and tests changes automatically as they are integrated", "Runs production databases only", "Writes all application code", "Replaces source control"]', 'Builds and tests changes automatically as they are integrated', 'CI automates validation of integrated changes.'),
  ('Technical fundamentals', 'technical', 'medium', 'What is the purpose of input validation?', '["Ensuring incoming data meets expected rules before processing", "Encrypting every database row", "Creating user accounts automatically", "Reducing screen resolution"]', 'Ensuring incoming data meets expected rules before processing', 'Validation checks that inputs have acceptable formats, ranges, and values.'),
  ('Technical fundamentals', 'technical', 'medium', 'What is a race condition?', '["A result that depends on the timing or interleaving of concurrent operations", "A sorting algorithm", "A network cable fault", "A database backup strategy"]', 'A result that depends on the timing or interleaving of concurrent operations', 'Race conditions arise when concurrent access to shared state makes behavior timing-dependent.'),
  ('Technical fundamentals', 'technical', 'medium', 'What is technical debt?', '["Future maintenance cost caused by expedient design or implementation choices", "A payment owed for computer hardware", "The size of a source repository", "A type of network latency"]', 'Future maintenance cost caused by expedient design or implementation choices', 'Technical debt describes tradeoffs that may speed delivery now but create future engineering cost.')
) as q(topic_name, question_type, difficulty, prompt, options, correct_answer, explanation)
join public.topics t on t.name = q.topic_name
on conflict (topic_id, prompt) do nothing;

commit;

select t.name as topic, count(q.id) as question_count
from public.topics t
left join public.questions q on q.topic_id = t.id and q.active
where t.name in (
  'CN', 'DBMS', 'DSA', 'HR', 'Java', 'OS', 'Python', 'Quant',
  'Technical fundamentals'
)
group by t.name
order by t.name;
